//! AZEL conversions whose LAST comes from the caches C keeps: the LAST
//! each SkyFrame extrapolates for Epoch changes under 0.4 day, and the
//! table of LAST values already computed, which interpolates between
//! tabulated epochs.
//!
//! `sky_last_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/sky_last_probe.c`, which runs its steps in one
//! process. The test runs the same steps in the same order on one thread,
//! since the table is per thread, so each step sees the caches the earlier
//! steps left, as in C.

#[path = "sky_last_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{FrameRef, FrameSearch, FrameSet, SkyFrame, SkySystem};
use starlink_ast::mappings::Mapping;

fn sky(system: SkySystem, epoch: f64, obslon: f64) -> SkyFrame {
    let mut f = SkyFrame::unset_system();
    f.set_system(system);
    f.set_epoch_mjd(epoch);
    f.set_obs_lat(0.3459);
    f.set_obs_lon(obslon);
    f
}

fn set_epochs(a: &mut SkyFrame, b: &mut SkyFrame, epoch: f64) {
    a.set_epoch_mjd(epoch);
    b.set_epoch_mjd(epoch);
}

/// Convert `from` to `to` and transform the probe's points.
fn step(from: &mut SkyFrame, to: &mut SkyFrame) -> [[f64; 2]; 3] {
    let fs = from.convert_to(to, &[]).unwrap().expect("a conversion");
    let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
    let xin: Vec<f64> = cases::POINTS.iter().map(|p| p[0]).collect();
    let yin: Vec<f64> = cases::POINTS.iter().map(|p| p[1]).collect();
    let (x, y) = map.tran2(&xin, &yin, true).unwrap();
    [[x[0], y[0]], [x[1], y[1]], [x[2], y[2]]]
}

#[test]
fn cached_last_follows_the_c_library() {
    let (e0, lon) = (cases::E0, cases::LON);
    let mut got: Vec<(&str, [[f64; 2]; 3])> = Vec::new();

    let mut azel = sky(SkySystem::Azel, e0, lon);
    let mut icrs = sky(SkySystem::Icrs, e0, lon);
    got.push(("pair_e0", step(&mut azel, &mut icrs)));
    set_epochs(&mut azel, &mut icrs, e0 + 0.1);
    got.push(("pair_plus_0.1", step(&mut azel, &mut icrs)));
    set_epochs(&mut azel, &mut icrs, e0 + 0.5);
    got.push(("pair_plus_0.5", step(&mut azel, &mut icrs)));
    set_epochs(&mut azel, &mut icrs, e0 + 0.45);
    got.push(("pair_plus_0.45", step(&mut azel, &mut icrs)));
    got.push(("pair_reverse", step(&mut icrs, &mut azel)));

    let mut a = sky(SkySystem::Azel, e0 + 0.25, lon);
    let mut b = sky(SkySystem::Icrs, e0 + 0.25, lon);
    got.push(("fresh_plus_0.25", step(&mut a, &mut b)));
    set_epochs(&mut a, &mut b, e0);
    got.push(("fresh_e0", step(&mut a, &mut b)));

    let mut a = sky(SkySystem::Azel, e0 + 0.25, lon + 0.5);
    let mut b = sky(SkySystem::Icrs, e0 + 0.25, lon + 0.5);
    got.push(("other_lon_plus_0.25", step(&mut a, &mut b)));

    let mut a = sky(SkySystem::Fk5, e0 + 2.0, lon);
    let mut b = sky(SkySystem::Icrs, e0 + 2.3, lon);
    got.push(("fk5_plus_2", step(&mut a, &mut b)));
    let mut a = sky(SkySystem::Azel, e0 + 2.1, lon);
    let mut b = sky(SkySystem::Icrs, e0 + 2.1, lon);
    got.push(("azel_after_fk5", step(&mut a, &mut b)));

    let mut copy = azel.clone();
    copy.set_epoch_mjd(e0 + 0.6);
    got.push(("copy_plus_0.6", step(&mut copy, &mut icrs)));

    azel.set_obs_lon(lon + 0.5);
    icrs.set_obs_lon(lon + 0.5);
    set_epochs(&mut azel, &mut icrs, e0 + 0.35);
    got.push(("pair_new_lon_plus_0.35", step(&mut azel, &mut icrs)));

    let names: Vec<&str> = got.iter().map(|g| g.0).collect();
    let want_names: Vec<&str> = cases::STEPS.iter().map(|s| s.0).collect();
    assert_eq!(names, want_names, "the test runs the probe's steps");
    let failures: Vec<String> = got
        .iter()
        .zip(cases::STEPS)
        .filter(|(g, w)| !crate::common::c_values_eq(g.1.as_flattened(), w.1.as_flattened()))
        .map(|(g, w)| format!("{}: got {:?}, C gives {:?}", g.0, g.1, w.1))
        .collect();
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Transform the probe's points through `cvt`.
fn points(cvt: &FrameSet) -> [[f64; 2]; 3] {
    let xin: Vec<f64> = cases::POINTS.iter().map(|p| p[0]).collect();
    let yin: Vec<f64> = cases::POINTS.iter().map(|p| p[1]).collect();
    let (x, y) = cvt.tran2(&xin, &yin, true).unwrap();
    [[x[0], y[0]], [x[1], y[1]], [x[2], y[2]]]
}

// An AZEL SkyFrame inside a FrameSet keeps the LAST it computes across
// conversions of the FrameSet, as one converted directly does, so a change
// of Epoch under 0.4 day extrapolates it.
// Values from tools/oracle_fixtures/frameset_last_probe.c.
#[test]
#[allow(clippy::excessive_precision)] // 17 digits, so the C values read back exactly
fn a_frameset_member_keeps_its_cached_last() {
    const STEPS: [(&str, f64, [[f64; 2]; 3]); 4] = [
        (
            "e0",
            0.0,
            [
                [3.5775542230687107, 0.65529042636910739],
                [6.2301496148307791, -0.58611966251315417],
                [2.2594791074935849, 0.59512118783272816],
            ],
        ),
        (
            "plus_0.1",
            0.1,
            [
                [4.2079773122463449, 0.65489446359345305],
                [0.5774247306448278, -0.58593155281489762],
                [2.8898206248374603, 0.59548777894224925],
            ],
        ),
        (
            "plus_0.2",
            0.2,
            [
                [4.8381723552049021, 0.6542902600966608],
                [1.2077027700038605, -0.58541218765104353],
                [3.5202652721300987, 0.5954854423642868],
            ],
        ),
        (
            "plus_0.35",
            0.35,
            [
                [5.7829379765830327, 0.65350134786535496],
                [2.1526058615684747, -0.58446503438470887],
                [4.4657874418107237, 0.5948320834871238],
            ],
        ),
    ];
    const REVERSE: [[f64; 2]; 3] = [
        [0.48236421263451101, -0.62183856163994111],
        [3.3867489100596382, 0.27959613814207229],
        [0.28387300653166092, 0.4016498791056195],
    ];
    let (e0, lon) = (cases::E0, cases::LON);
    let mut fs = FrameSet::new(Box::new(sky(SkySystem::Azel, e0, lon)));
    let mut icrs = sky(SkySystem::Icrs, e0, lon);
    let mut failures = Vec::new();
    for (name, de, want) in STEPS {
        fs.frame_mut(FrameRef::Current)
            .unwrap()
            .set_epoch_mjd(e0 + de)
            .unwrap();
        icrs.set_epoch_mjd(e0 + de);
        let cvt = fs.convert_to(&mut icrs, &[]).unwrap().unwrap();
        let got = points(&cvt);
        if !crate::common::c_values_eq(got.as_flattened(), want.as_flattened()) {
            failures.push(format!("{name}: got {got:?}, C gives {want:?}"));
        }
    }
    let cvt = icrs.convert_to(&mut fs, &[]).unwrap().unwrap();
    let got = points(&cvt);
    if !crate::common::c_values_eq(got.as_flattened(), REVERSE.as_flattened()) {
        failures.push(format!("reverse: got {got:?}, C gives {REVERSE:?}"));
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
